     for(let i=0;i<state.board.length;i++){const u=state.board[i]; if(u&&u.star===star){ if(!groups.has(u.charId))groups.set(u.charId,[]); groups.get(u.charId).push({u,type:'board',idx:i});}}
     for(let i=0;i<state.bench.length;i++){...}
     for(const [id,list] of groups){
       if(list.length>=3){
         const keeperEntry = list.find(e=>e.type==='board') || list[0];
         const others = list.filter(e=>e!==keeperEntry).slice(0,2);
         others.forEach(e=>{ if(e.type==='board') state.board[e.idx]=null; else state.bench[e.idx]=null; if(state.sel && state.sel.unit===e.u) state.sel=null; });
         keeperEntry.u.star++;
