    const c = CHARS_BY_ID[sel.unit.charId];
    const st = statFor(sel.unit);
    const f = FACTIONS[c.faction], r = ROLES[c.role];
    const price = sellPrice(sel.unit);
    els.detail.innerHTML = `<div class="detail-top">` +
