+  function startTimer() {
+    clearInterval(timerId);
+    state.timer = PREP_TIME;
+    updateTimerUI();
+    timerId = setInterval(() => {
+      if (state.screen !== 'game' || state.phase !== 'prep' || state.paused) return;
+      state.timer--;
+      updateTimerUI();
+      if (state.timer <= 0) {
+        state.timer = 0;
+        startBattle();
+      }
+    }, 1000);
+  }
+  function clearTimer() {
+    clearInterval(timerId);
+    timerId = null;
+  }
+
+  function renderAll() {
+    if (state.phase !== 'combat') renderBoard();
+    renderBench();
+    renderShop();
+    renderHUD();
+    renderSynergies();
+    renderNextWave();
+    renderDetail();
+    updateSelBar();
+    updateCellVar();
+    if (state.sel && state.phase === 'prep') refreshSelectionUI();
+  }
+
+  /* ---------------- boot / title ---------------- */
+  function buildBoardCells() {
+    for (let r = 0; r < ROWS; r++) {
+      for (let c = 0; c < COLS; c++) {
+        const idx = r * COLS + c;
+        const cell = document.createElement('div');
+        cell.className = 'cell ' + ((r + c) % 2 ? 'alt ' : '') + (r < PLAYER_START_ROW ? 'enemy' : 'player');
+        cell.dataset.cell = idx;
+        cell.dataset.r = r;
+        cell.dataset.c = c;
+        els.board.appendChild(cell);
+        cells.push(cell);
+      }
+    }
+    els.board.addEventListener('click', (e) => {
+      const cell = e.target.closest('.cell');
+      if (cell) onCellClick(Number(cell.dataset.cell));
+    });
+  }
+
+  function renderTitleAgents() {
+    const pool = CHARS.filter(c => c.cost >= 4);
+    const chosen = [];
+    while (chosen.length < 6 && pool.length) {
+      const i = rand(pool.length);
+      chosen.push(pool.splice(i, 1)[0]);
+    }
+    els.titleAgents.innerHTML = chosen.map(c =>
+      `<div class="t-agent" style="--c1:${c.c1};--c2:${c.c2};animation-delay:${(Math.random() * 4).toFixed(1)}s" data-face="${c.name[0]}"><span>${c.en}</span></div>`
+    ).join('');
+  }
+
+  /*__PART3__*/
 })();

