Mana bar width.

Combat loop:
```js
function combatLoop(now){
 if(!combat||combat.over) return;
 let dt=(now-combat.last)/1000; combat.last=now;
 dt=clamp(dt,0,0.06)*state.speed;
 stepCombat(dt);
 if(combat && !combat.over) combat.raf=requestAnimationFrame(combatLoop);
}
function stepCombat(dt){
 combat.time+=dt;
 const units=combat.units;
 for(const u of units){
  if(!u.alive) continue;
  if(u.el) updateCombatToken(u); // after movement; maybe at end
  if(u.timed.length){...}
  if(u.castLock>0){u.castLock-=dt;}
  if(u.stun>0){u.stun=Math.max(0,u.stun-dt); continue;}
  if(u.castLock>0) continue;
  let target=u.target;
  if(!target||!target.alive||target.side===u.side){
    target=nearestEnemy(u);
    u.target=target;
  }
  if(!target) continue;
  if(cheb(u.pos,target.pos)<=u.range){
    u.cd-=dt;
    if(u.cd<=0){
      doAttack(u,target);
      if(!u.alive) continue;
      if(u.mana>=u.manaMax){ castAbility(u,target); }
    }
  } else {
    u.moveCd-=dt;
    if(u.moveCd<=0){ moveToward(u,target); u.moveCd=0.36; }
  }
 }
 // update tokens
 for(const u of units) if(u.alive||u.el) updateCombatToken(u);
 // end
 if(!units.some(u=>u.alive&&u.side==='enemy')) { endCombat(true); return; }
 if(!units.some(u=>u.alive&&u.side==='player')) { endCombat(false); return; }
 if(combat.time>=45){ endCombat(false,'timeout'); return; }
}
```
Casting after attack means mana hits full on attack, then cast immediately. Also units that start with full mana (synergy) should cast before moving. Add at top after stun:
```js
if(u.mana>=u.manaMax){ castAbility(u, u.target || nearestEnemy(u)); continue; }
```
But castAbility sets target maybe. Add.

Important: if cast while target null, use nearest. In cast, compute target.

`doAttack`:
```js
const spd = Math.max(0.25,u.atkSpd+u.buffSpd);
u.cd=1/spd;
const dmg = u.atk*(1+u.buffAtk);
dealDamage(u,target,dmg,false);
u.mana=Math.min(u.manaMax,u.mana+10);
if(u.lifesteal>0) healUnit(u, dmg*u.lifesteal, null);
if(u.side==='player') sfx? skip.
```
Every basic attack creates float text; that's a lot but visual feedback. Use smaller numbers. Fine.

`dealDamage(src,tgt,raw,isAbility)`:
```js
if(!tgt.alive) return 0;
let dmg=raw;
if(isAbility) dmg*=1+(src?src.abilityMul:0);
dmg*=100/(100+Math.max(0,tgt.armor));
dmg*=1-Math.min(0.6,tgt.buffDr||0);
if(tgt.shield>0){...}
dmg=Math.max(1,Math.round(dmg)); // rounding before? after shield
tgt.hp-=dmg;
if(src) src.totalDamage=(src.totalDamage||0)+dmg;
floatText(tgt.pos, '-'+dmg, isAbility?'ability':'dmg');
tgt.mana=Math.min(tgt.manaMax,tgt.mana+(isAbility?4:6));
if(tgt.el){tgt.el.classList.add('hit'); setTimeout(()=>tgt.el&&tgt.el.classList.remove('hit'),120);}
if(tgt.hp<=0) killUnit(tgt,src);
